// virtual parameter for WPA passphrase
let m = "";
if (args[1].value) {
  m = args[1].value[0];
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.KeyPassphrase", null, {value: m});
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.PreSharedKey.1.KeyPassphrase", null, {value: m});
}
else {
  let d = declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.KeyPassphrase", {value: 1});
  let igd = declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.PreSharedKey.1.KeyPassphrase", {value: 1});

  if (d.size && d.value && d.value[0]) {
    m = d.value[0];
  }
  else if (igd.size && igd.value && igd.value[0]) {
    m = igd.value[0];
  }
}

return {writable: true, value: [m, "xsd:string"]};

// Total active all ssid
let active = 0;
let isNumber = (value) => {
  return typeof value === "number" && isFinite(value);
};

let ssid1 = declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.TotalAssociations", {value: 1});

if (ssid1 && ssid1.size && isNumber(ssid1.value[0])) {
  active += ssid1.value[0];
}

return {writable: false, value: [String(active), "xsd:unsignedInt"]};

// ALIJAYA NET - Universal MAC Address
let mac = "";
let paths = [
  "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.MACAddress",
  "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.MACAddress",
  "InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MACAddress",
  "InternetGatewayDevice.DeviceInfo.X_CU_SerialNumber",
  "Device.PPP.Interface.*.MACAddress"
];

for (let i = 0; i < paths.length; i++) {
  let d = declare(paths[i], {value: 1});
  for (let p of d) {
    if (p.value && p.value[0] && typeof p.value[0] === 'string') {
      let val = p.value[0].trim();
      if (val !== "" && val !== "00:00:00:00:00:00" && val.includes(":")) {
        mac = val;
        break;
      }
    }
  }
  if (mac !== "") break;
}

return {writable: false, value: [mac || "Ethernet", "xsd:string"]};

// ALIJAYA NET - Universal PPPoE Uptime
let totalSecs = 0;
let paths = [
  "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Uptime",
  "InternetGatewayDevice.DeviceInfo.UpTime",
  "Device.DeviceInfo.UpTime"
];

for (let i = 0; i < paths.length; i++) {
  let d = declare(paths[i], {value: 1});
  for (let p of d) {
    if (p.value && p.value[0] !== undefined) {
      let s = parseInt(p.value[0], 10);
      if (!isNaN(s) && s > 0) {
        totalSecs = s;
        break;
      }
    }
  }
  if (totalSecs > 0) break;
}

if (totalSecs <= 0) {
  return {writable: false, value: ["0d 00:00:00", "xsd:string"]};
}

let days = Math.floor(totalSecs / 86400);
let rem  = totalSecs % 86400;
let hrs  = Math.floor(rem / 3600);
let mins = Math.floor((rem % 3600) / 60);
let secs = rem % 60;

let pad = (n) => (n < 10 ? "0" + n : "" + n);
let uptime = days + "d " + pad(hrs) + ":" + pad(mins) + ":" + pad(secs);

return {writable: false, value: [uptime, "xsd:string"]};

// ALIJAYA NET - Universal PPPoE Username
let username = "N/A";
let paths = [
  "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Username",
  "Device.PPP.Interface.*.Username"
];

for (let i = 0; i < paths.length; i++) {
  let d = declare(paths[i], {value: 1});
  for (let p of d) {
    if (p.value && p.value[0] !== undefined && p.value[0] !== null && p.value[0] !== "") {
      let val = String(p.value[0]).trim();
      if (val !== "") {
        username = val;
        break;
      }
    }
  }
  if (username !== "N/A") break;
}

return {writable: false, value: [username, "xsd:string"]};

let zte = declare("InternetGatewayDevice.WANDevice.*.X_ZTE-COM_WANPONInterfaceConfig.RXPower", { value: Date.now() });
let huawei = declare("InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.RXPower", { value: Date.now() });
let fiberhome = declare("InternetGatewayDevice.WANDevice.*.X_FH_GponInterfaceConfig.RXPower", { value: Date.now() });
let ztecmcc = declare("InternetGatewayDevice.WANDevice.*.X_CMCC_EponInterfaceConfig.RXPower", { value: Date.now() });
let ztecmcg = declare("InternetGatewayDevice.WANDevice.*.X_CMCC_GponInterfaceConfig.RXPower", { value: Date.now() });
let gm220se = declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower", { value: Date.now() });
let gm220sg = declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower", { value: Date.now() });
let f477v2 = declare("InternetGatewayDevice.WANDevice.*.X_CU_WANEPONInterfaceConfig.OpticalTransceiver.RXPower", { value: Date.now() });

let m = "";
if (zte.value !== undefined) { m = (zte.value[0] / 100 - 100).toFixed(2); }
else if (huawei.value !== undefined) { m = (huawei.value[0] / 100).toFixed(2); }
else if (fiberhome.value !== undefined) { m = (fiberhome.value[0] / 100).toFixed(2); }
else if (ztecmcc.value !== undefined) { m = (ztecmcc.value[0] / 1000).toFixed(2); }
else if (ztecmcg.value !== undefined) { m = (ztecmcg.value[0] / 500 - 40).toFixed(2); }
else if (gm220se.value !== undefined) { m = (gm220se.value[0] / 10000).toFixed(2); }
else if (gm220sg.value !== undefined) { m = (gm220sg.value[0] / 10000).toFixed(2); }
else if (f477v2.value !== undefined) { m = (f477v2.value[0] / 100).toFixed(2); }

return {writable: false, value: [m || "-", "xsd:string"]};

