return {writable: false, value: [ip, "xsd:string"]};

const brand = declare('DeviceID.Manufacturer', { value: 1 }).value[0];

if (
    brand === 'Huawei Technologies Co., Ltd' || brand === 'ZTE' || brand === 'FiberHome' || brand === 'CIOT') {
