const uptimeParam = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Uptime", {value: now});

let totalSecs = 0;
if (uptimeParam && uptimeParam.value && uptimeParam.value.length > 0) {
  totalSecs += parseInt(uptimeParam.value[0], 10) || 0;
}
if (upTimeParam && upTimeParam.value && upTimeParam.value.length > 0) {
  totalSecs += parseInt(upTimeParam.value[0], 10) || 0;
}

const totalMillisecs = totalSecs * 1000;
return {writable: false, value: [String(totalMillisecs), "xsd:unsignedInt"]};

// ALIJAYA NET - Active WiFi Devices
let active = 0;
let paths = [
  "InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.TotalAssociations",
  "InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.AssociatedDeviceNumberOfEntries",
  "Device.WiFi.AccessPoint.*.AssociatedDeviceNumberOfEntries"
];

for (let p of paths) {
  let d = declare(p, {value: 1});
  for (let item of d) {
    if (item.value && item.value[0] !== undefined) {
      let count = parseInt(item.value[0], 10);
      if (!isNaN(count) && count > 0) {
        active += count;
      }
    }
  }
  if (active > 0) break;
}

return {writable: false, value: [active, "xsd:int"]};

// ALIJAYA NET - Temperature
let m = "N/A";
let paths = [
  "InternetGatewayDevice.WANDevice.*.X_ZTE-COM_WANPONInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.*.X_FH_GponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.*.X_CMCC_EponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.*.X_CMCC_GponInterfaceConfig.TransceiverTemperature"
];

for (let p of paths) {
  let d = declare(p, {value: 1});
  for (let item of d) {
    if (item.value && item.value[0] !== undefined) {
      let val = parseFloat(item.value[0]);
      if (!isNaN(val)) {
        if (val < 150 && val > 0) {
          m = Math.round(val).toString();
        } else if (val >= 150) {
          let temp = val / 256;
          if (temp > 100 || temp < 10) {
            temp = (val * 0.0038) + 1.5;
          }
          m = Math.round(temp).toString();
        }
        if (m !== "N/A") break;
      }
    }
  }
  if (m !== "N/A") break;
}

return {writable: false, value: [m, "xsd:string"]};

// ALIJAYA NET - IP TR-069
let result = "";
let keys = [
  "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.ExternalIPAddress",
  "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ExternalIPAddress",
