// ALIJAYA NET - Universal Device Uptime
let totalSecs = 0;
let paths = [
  "InternetGatewayDevice.DeviceInfo.UpTime",
  "Device.DeviceInfo.UpTime",
  "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Uptime"
];

