        totalSecs = s;
        break;
      }
    }
  }
  if (totalSecs > 0) break;
}

if (totalSecs <= 0) {
  return {writable: false, value: ["0d 00:00:00", "xsd:string"]};
}

let days = Math.floor(totalSecs / 86400);
let rem  = totalSecs % 86400;
let hrs  = Math.floor(rem / 3600);
let mins = Math.floor((rem % 3600) / 60);
let secs = rem % 60;

let pad = (n) => (n < 10 ? "0" + n : "" + n);
let uptime = days + "d " + pad(hrs) + ":" + pad(mins) + ":" + pad(secs);

return {writable: false, value: [uptime, "xsd:string"]};

// ALIJAYA NET - Universal Serial Number
let sn = "";
let hexToText = (hex) => {
  let text = "";
  for (let i = 0; i < hex.length; i += 2) {
    let hexCode = hex.substr(i, 2);
    let charCode = parseInt(hexCode, 16);
    text += String.fromCharCode(charCode);
  }
  return text;
};

let paths = [
  "DeviceID.SerialNumber",
  "InternetGatewayDevice.DeviceInfo.SerialNumber",
  "Device.DeviceInfo.SerialNumber",
  "InternetGatewayDevice.DeviceInfo.X_HW_SerialNumber",
  "InternetGatewayDevice.DeviceInfo.X_CU_SerialNumber"
];

for (let i = 0; i < paths.length; i++) {
  let d = declare(paths[i], {value: 1});
  for (let p of d) {
    if (p.value && p.value[0]) {
      let val = String(p.value[0]).trim();
      if (val !== "") {
        sn = val;
        break;
      }
    }
  }
  if (sn !== "") break;
}

if (/^[0-9A-Fa-f]{12,}$/.test(sn) && !sn.includes("40ee15")) {
  let hexPart = sn.substr(0, 8);
  let textPart = hexToText(hexPart);
  sn = textPart + sn.substr(8);
}

return {writable: false, value: [sn, "xsd:string"]};

