const now = Date.now();

// Clear cached data model to force a refresh
clear("Device", now);
clear("InternetGatewayDevice", now);

// ALIJAYA NET - Bulletproof & Lean Default Provision
const now = Date.now();
const daily = now - 86400000; 
const update = now - 120000; // 2 minutes (auto-refresh on inform)

// 1. Safe Brand Detection
const merkDecl = declare("DeviceID.Manufacturer", {value: 1});
const merk = (merkDecl && merkDecl.value && merkDecl.value[0]) ? String(merkDecl.value[0]) : "";

// 2. Basic Info & Uptime
declare("DeviceID.ProductClass", {path: daily, value: daily});
declare("InternetGatewayDevice.DeviceInfo.HardwareVersion", {path: daily, value: daily});
declare("InternetGatewayDevice.DeviceInfo.SoftwareVersion", {path: daily, value: daily});
declare("InternetGatewayDevice.DeviceInfo.UpTime", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANCommonInterfaceConfig.WANAccessType", {path: daily, value: daily});

// 3. Optical Power & Temp (Safe paths by manufacturer)
if (merk.includes("ZTE") || merk.includes("ZICG")) {
  declare("InternetGatewayDevice.WANDevice.*.X_ZTE-COM_WANPONInterfaceConfig.RXPower", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_ZTE-COM_WANPONInterfaceConfig.TransceiverTemperature", {path: update, value: update});
} else if (merk.includes("Huawei")) {
  declare("InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.RXPower", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.TransceiverTemperature", {path: update, value: update});
} else {
  // CIOT / GM220-S / M63X / CT-COM
  declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.TransceiverTemperature", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.TransceiverTemperature", {path: update, value: update});
}

// 4. WAN Connection (Essential Status & IP refresh on inform; config parameters cached daily)
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Enable", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Name", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ConnectionType", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Username", {path: daily, value: daily});
