declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Uptime", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.NATEnabled", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ConnectionStatus", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Password", {path: daily, value: daily});

// Brand-aware VLAN & ServiceList
if (merk.includes("Huawei")) {
  declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_HW_VLAN", {path: daily, value: daily});
  declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_HW_SERVICELIST", {path: daily, value: daily});
} else if (merk.includes("ZTE") || merk.includes("ZICG")) {
  declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_ZTE-COM_VlanID", {path: daily, value: daily});
  declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.VLANID", {path: daily, value: daily});
} else {
  // CIOT / CT-COM / Standard
  declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CT-COM_VlanID", {path: daily, value: daily});
  declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.VLANID", {path: daily, value: daily});
  declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.X_CT-COM_ServiceList", {path: daily, value: daily});
}

// 5. WLAN (WiFi) Configuration
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*", {path: daily});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.SSID", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.BeaconType", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.Enable", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.Channel", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.TotalAssociations", {path: update, value: update});

if (merk.includes("ZTE") || merk.includes("ZICG") || merk.includes("Huawei")) {
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.PreSharedKey.1.KeyPassphrase", {path: daily, value: daily});
} else {
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.KeyPassphrase", {path: daily, value: daily});
}

// 6. LAN Management & Gateway Config
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.IPRouters", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.DHCPServerEnable", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MinAddress", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MaxAddress", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.DNSServers", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.IPInterface.1.IPInterfaceIPAddress", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.IPInterface.1.IPInterfaceSubnetMask", {path: daily, value: daily});

// 7. Ethernet Physical Ports (Safe object path)
declare("InternetGatewayDevice.LANDevice.1.LANEthernetInterfaceConfig.*", {path: daily});

// ALIJAYA NET - Provision Inform
